#!/usr/bin/env bash
# Fetch all screens (screenshot + HTML/SVG code) for the Stitch project
# "DFK Shadcn UI Redesign" (projects/2842323800619420280).
# Usage: bash stitch/fetch.sh
set -euo pipefail

cd "$(dirname "$0")"
mkdir -p screenshots html

# slug | screenshot url | code url | code extension
while IFS='|' read -r slug png html ext; do
  [ -z "$slug" ] && continue
  echo "Fetching: $slug"
  curl -sSL --fail -o "screenshots/$slug.png" "$png"
  curl -sSL --fail -o "html/$slug.$ext" "$html"
done <<'EOF'
